The good news: pforge handlers are compatible with pmcp! Both frameworks share the same handler trait pattern, making migration straightforward. // This handler works in BOTH pforge and pmcp
use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use schemars::JsonSchema; #[derive(Debug, Deserialize, JsonSchema)]
pub struct CalculateInput { a: f64, b: f64, operation: String,
} #[derive(Debug, Serialize, JsonSchema)]
pub struct CalculateOutput { result: f64,
} pub struct CalculateHandler; #[async_trait]
impl pforge_runtime::Handler for CalculateHandler { type Input = CalculateInput; type Output = CalculateOutput; type Error = pforge_runtime::Error; async fn handle(&self, input: Self::Input) -> pforge_runtime::Result<Self::Output> { let result = match input.operation.as_str() { "add" => input.a + input.b, "subtract" => input.a - input.b, "multiply" => input.a * input.b, "divide" => { if input.b == 0.0 { return Err(pforge_runtime::Error::Handler( "Division by zero".into() )); } input.a / input.b } _ => return Err(pforge_runtime::Error::Handler( "Unknown operation".into() )), }; Ok(CalculateOutput { result }) }
}

