use pforge_runtime::{Handler, Result, Error};
use serde::{Deserialize, Serialize};
use schemars::JsonSchema; #[derive(Debug, Deserialize, JsonSchema)]
pub struct CalcInput { a: f64, b: f64, operation: String,
} #[derive(Debug, Serialize, JsonSchema)]
pub struct CalcOutput { result: f64,
} pub struct CalculateHandler; #[async_trait::async_trait]
impl Handler for CalculateHandler { type Input = CalcInput; type Output = CalcOutput; type Error = Error; async fn handle(&self, input: Self::Input) -> Result<Self::Output> { let result = match input.operation.as_str() { "add" => input.a + input.b, "subtract" => input.a - input.b, "multiply" => input.a * input.b, "divide" => { if input.b == 0.0 { return Err(Error::Handler("Division by zero".into())); } input.a / input.b } _ => return Err(Error::Handler("Unknown operation".into())), }; // State is managed automatically self.state.set("last_result", &result.to_string(), None).await?; Ok(CalcOutput { result }) }
