async fn test_retry_with_timeout() { let policy = RetryPolicy::new(3) .with_backoff(Duration::from_millis(10), Duration::from_millis(50)) .with_jitter(false); let attempt_counter = Arc::new(AtomicUsize::new(0)); let counter_clone = attempt_counter.clone(); let result = retry_with_policy(&policy, || { let counter = counter_clone.clone(); async move { let count = counter.fetch_add(1, Ordering::SeqCst); if count < 2 { with_timeout(Duration::from_millis(10), async { tokio::time::sleep(Duration::from_secs(10)).await; 42 }) .await } else { Ok(100) } } }) .await; assert!(result.is_ok()); assert_eq!(result.unwrap(), 100); assert_eq!(attempt_counter.load(Ordering::SeqCst), 3);
} What this tests : Retry policy execution Timeout integration Backoff behavior Success after multiple attempts

