Property 1: Serialization Roundtrip Invariant : Serializing and deserializing a config preserves its structure. proptest! { #[test] fn config_serialization_roundtrip(config in arb_forge_config()) { // YAML roundtrip let yaml = serde_yml::to_string(&config).unwrap(); let parsed: ForgeConfig = serde_yml::from_str(&yaml).unwrap(); // Key properties preserved prop_assert_eq!(&config.forge.name, &parsed.forge.name); prop_assert_eq!(&config.forge.version, &parsed.forge.version); prop_assert_eq!(config.tools.len(), parsed.tools.len()); }
} Edge cases found : Empty strings, special characters, Unicode in names. Property 2: Tool Name Uniqueness Invariant : After validation, all tool names are unique. proptest! { #[test] fn tool_names_unique(config in arb_forge_config()) { let mut names = std::collections::HashSet::new(); for tool in &config.tools { prop_assert!(names.insert(tool.name())); } }
} Edge cases found : Case sensitivity, whitespace differences. Property 3: Valid Configs Pass Validation Invariant : Configs generated by our generators always pass validation. proptest! { #[test] fn valid_configs_pass_validation(config in arb_forge_config()) { let result = validate_config(&config); prop_assert!(result.is_ok(), "Valid config failed validation: {:?}", result); }
} Edge cases found : Empty tool lists, minimal configs. Property 4: Handler Paths Contain Separator Invariant : Native tool handler paths always contain ::. proptest! { #[test] fn native_handler_paths_valid(config in arb_forge_config()) { for tool in &config.tools { if let ToolDef::Native { handler, .. } = tool { prop_assert!(handler.path.contains("::"), "Handler path '{}' doesn't contain ::", handler.path); } } }
} Edge cases found : Single-segment paths, paths with multiple separators. Property 5: Transport Types Serialize Correctly Invariant : Transport types roundtrip through serialization. proptest! { #[test] fn transport_types_valid(config in arb_forge_config()) { let yaml = serde_yml::to_string(&config.forge.transport).unwrap(); let parsed: TransportType = serde_yml::from_str(&yaml).unwrap(); prop_assert_eq!(config.forge.transport, parsed); }
} Property 6: Tool Names Follow Conventions Invariant : Tool names are lowercase alphanumeric with hyphens/underscores, length 3-50. proptest! { #[test] fn tool_names_follow_conventions(config in arb_forge_config()) { for tool in &config.tools { let name = tool.name(); prop_assert!(name.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-' || c == '_' ), "Tool name '{}' doesn't follow conventions", name); prop_assert!(name.len() >= 3 && name.len() <= 50, "Tool name '{}' length {} not in range 3-50", name, name.len()); } }
}

