// From crates/pforge-runtime/src/middleware.rs pub async fn execute<F, Fut>(&self, mut request: Value, handler: F) -> Result<Value>
where F: FnOnce(Value) -> Fut, Fut: std::future::Future<Output = Result<Value>>,
{ // Execute "before" phase in order for middleware in &self.middlewares { request = middleware.before(request).await?; } // Execute handler let result = handler(request.clone()).await; // Execute "after" phase in reverse order or "on_error" if failed match result { Ok(mut response) => { for middleware in self.middlewares.iter().rev() { response = middleware.after(request.clone(), response).await?; } Ok(response) } Err(error) => { let mut current_error = error; for middleware in self.middlewares.iter().rev() { match middleware.on_error(request.clone(), current_error).await { Ok(recovery_response) => return Ok(recovery_response), Err(new_error) => current_error = new_error, } } Err(current_error) } }
}

