The PromptManager handles template interpolation at runtime: // From crates/pforge-runtime/src/prompt.rs
impl PromptManager { pub fn render(&self, name: &str, args: HashMap<String, Value>) -> Result<String> { let entry = self .prompts .get(name) .ok_or_else(|| Error::Handler(format!("Prompt '{}' not found", name)))?; // Validate required arguments self.validate_arguments(entry, &args)?; // Perform template interpolation self.interpolate(&entry.template, &args) } fn interpolate(&self, template: &str, args: &HashMap<String, Value>) -> Result<String> { let mut result = template.to_string(); for (key, value) in args { let placeholder = format!("{{{{{}}}}}", key); let replacement = match value { Value::String(s) => s.clone(), Value::Number(n) => n.to_string(), Value::Bool(b) => b.to_string(), Value::Null => String::new(), _ => serde_json::to_string(value) .map_err(|e| Error::Handler(format!("Serialization error: {}", e)))?, }; result = result.replace(&placeholder, &replacement); } // Check for unresolved placeholders if result.contains("{{") && result.contains("}}") { let unresolved: Vec<&str> = result .split("{{") .skip(1) .filter_map(|s| s.split("}}").next()) .collect(); if !unresolved.is_empty() { return Err(Error::Handler(format!( "Unresolved template variables: {}", unresolved.join(", ") ))); } } Ok(result) }
} Error Handling: Missing required arguments → validation error Unresolved placeholders → rendering error Type mismatches → serialization error

