use rustc_hash::FxHashMap;
use std::sync::Arc; pub struct HandlerRegistry { /// FxHash for non-cryptographic, high-performance hashing /// 2x faster than SipHash for small keys (tool names typically < 20 chars) handlers: FxHashMap<&'static str, Arc<dyn HandlerEntry>>,
} impl HandlerRegistry { /// O(1) average case lookup #[inline(always)] pub fn get(&self, name: &str) -> Option<&Arc<dyn HandlerEntry>> { self.handlers.get(name) } /// Register handler with compile-time string interning pub fn register<H>(&mut self, name: &'static str, handler: H) where H: Handler + 'static, { self.handlers.insert(name, Arc::new(HandlerWrapper::new(handler))); }
