pub fn validate_config(config: &ForgeConfig) -> Result<(), ValidationError> { // Check for duplicate tool names let mut names = HashSet::new(); for tool in &config.tools { if !names.insert(tool.name()) { return Err(ValidationError::DuplicateTool(tool.name().to_string())); } } // Validate handler references for tool in &config.tools { if let ToolDef::Native { handler, .. } = tool { validate_handler_path(&handler.path)?; } } // Validate parameter schemas for tool in &config.tools { if let ToolDef::Native { params, .. } = tool { validate_param_schema(params)?; } } // Validate pipeline references for tool in &config.tools { if let ToolDef::Pipeline { steps, .. } = tool { for step in steps { if !names.contains(&step.tool) { return Err(ValidationError::UnknownTool(step.tool.clone())); } } } } Ok(())
} fn validate_handler_path(path: &str) -> Result<(), ValidationError> { // Check format: module::submodule::function_name if !path.contains("::") { return Err(ValidationError::InvalidHandlerPath(path.to_string())); } // Ensure valid Rust identifier for segment in path.split("::") { if !is_valid_identifier(segment) { return Err(ValidationError::InvalidIdentifier(segment.to_string())); } } Ok(())
}

