) -> Result<()> { let (ty, required, description) = match param_type { ParamType::Simple(simple_ty) => (rust_type_from_simple(simple_ty), true, None), ParamType::Complex { ty, required, description, .. } => (rust_type_from_simple(ty), *required, description.clone()), }; // Add doc comment if let Some(desc) = description { output.push_str(&format!(" /// {}\n", desc)); } // Add field if required { output.push_str(&format!(" pub {}: {},\n", field_name, ty)); } else { output.push_str(&format!(" pub {}: Option<{}>,\n", field_name, ty)); } Ok(())
