The bridge uses a stable C ABI for interoperability: // crates/pforge-bridge/src/lib.rs
use std::os::raw::{c_char, c_int};
use std::ffi::{CStr, CString};
use std::slice; /// Opaque handle to a handler instance
#[repr(C)]
pub struct HandlerHandle { _private: [u8; 0],
} /// Result structure for FFI
#[repr(C)]
pub struct FfiResult { /// 0 = success, non-zero = error code pub code: c_int, /// Pointer to result data (JSON bytes) pub data: *mut u8, /// Length of result data pub data_len: usize, /// Error message (null if success) pub error: *const c_char,
} /// Initialize a handler
///
/// # Safety
/// - `handler_type` must be a valid null-terminated string
/// - `config` must be a valid null-terminated JSON string
/// - Returned handle must be freed with `pforge_handler_free`
#[no_mangle]
pub unsafe extern "C" fn pforge_handler_init( handler_type: *const c_char, config: *const c_char,
) -> *mut HandlerHandle { let handler_type = match CStr::from_ptr(handler_type).to_str() { Ok(s) => s, Err(_) => return std::ptr::null_mut(), }; let config = match CStr::from_ptr(config).to_str() { Ok(s) => s, Err(_) => return std::ptr::null_mut(), }; // Initialize handler based on type let handler = match handler_type { "python" => PythonHandler::new(config), "go" => GoHandler::new(config), "nodejs" => NodeJsHandler::new(config), _ => return std::ptr::null_mut(), }; Box::into_raw(Box::new(handler)) as *mut HandlerHandle
} /// Execute a handler with given parameters
///
/// # Safety
/// - `handle` must be a valid handle from `pforge_handler_init`
/// - `params` must be valid UTF-8 JSON
/// - `params_len` must be the correct length
/// - Caller must free result with `pforge_result_free`
#[no_mangle]
pub unsafe extern "C" fn pforge_handler_execute( handle: *mut HandlerHandle, params: *const u8, params_len: usize,
) -> FfiResult { if handle.is_null() || params.is_null() { return FfiResult { code: -1, data: std::ptr::null_mut(), data_len: 0, error: CString::new("Null pointer").unwrap().into_raw(), }; } let handler = &*(handle as *mut Box<dyn Handler>); let params_slice = slice::from_raw_parts(params, params_len); match handler.execute(params_slice) { Ok(result) => { let result_vec = result.into_boxed_slice(); let result_len = result_vec.len(); let result_ptr = Box::into_raw(result_vec) as *mut u8; FfiResult { code: 0, data: result_ptr, data_len: result_len, error: std::ptr::null(), } } Err(e) => { let error_msg = CString::new(e.to_string()).unwrap(); FfiResult { code: -1, data: std::ptr::null_mut(), data_len: 0, error: error_msg.into_raw(), } } }
} /// Free a handler handle
///
/// # Safety
/// - `handle` must be a valid handle from `pforge_handler_init`
/// - `handle` must not be used after this call
#[no_mangle]
pub unsafe extern "C" fn pforge_handler_free(handle: *mut HandlerHandle) { if !handle.is_null() { drop(Box::from_raw(handle as *mut Box<dyn Handler>)); }
} /// Free a result structure
///
/// # Safety
/// - `result` must be from `pforge_handler_execute`
/// - `result` must not be freed twice
#[no_mangle]
pub unsafe extern "C" fn pforge_result_free(result: FfiResult) { if !result.data.is_null() { drop(Box::from_raw(slice::from_raw_parts_mut( result.data, result.data_len, ))); } if !result.error.is_null() { drop(CString::from_raw(result.error as *mut c_char)); }
}

