// bridges/go/pforge.go
package pforge /*
#cgo LDFLAGS: -L${SRCDIR} -lpforge_bridge
#include <stdlib.h> typedef struct HandlerHandle HandlerHandle; typedef struct { int code; unsigned char *data; size_t data_len; const char *error;
} FfiResult; HandlerHandle* pforge_handler_init(const char* handler_type, const char* config);
FfiResult pforge_handler_execute(HandlerHandle* handle, const unsigned char* params, size_t params_len);
void pforge_handler_free(HandlerHandle* handle);
void pforge_result_free(FfiResult result);
*/
import "C"
import ( "encoding/json" "errors" "unsafe"
) // Handler interface for Go handlers
type Handler interface { Handle(params map[string]interface{}) (map[string]interface{}, error)
} // PforgeHandler wraps the FFI handle
type PforgeHandler struct { handle *C.HandlerHandle
} // NewHandler creates a new pforge handler
func NewHandler(config map[string]interface{}) (*PforgeHandler, error) { configJSON, err := json.Marshal(config) if err != nil { return nil, err } handlerType := C.CString("go") defer C.free(unsafe.Pointer(handlerType)) configStr := C.CString(string(configJSON)) defer C.free(unsafe.Pointer(configStr)) handle := C.pforge_handler_init(handlerType, configStr) if handle == nil { return nil, errors.New("failed to initialize handler") } return &PforgeHandler{handle: handle}, nil
} // Execute runs the handler with given parameters
func (h *PforgeHandler) Execute(params map[string]interface{}) (map[string]interface{}, error) { paramsJSON, err := json.Marshal(params) if err != nil { return nil, err } result := C.pforge_handler_execute( h.handle, (*C.uchar)(unsafe.Pointer(&paramsJSON[0])), C.size_t(len(paramsJSON)), ) defer C.pforge_result_free(result) if result.code != 0 { errorMsg := C.GoString(result.error) return nil, errors.New(errorMsg) } resultBytes := C.GoBytes(unsafe.Pointer(result.data), C.int(result.data_len)) var output map[string]interface{} if err := json.Unmarshal(resultBytes, &output); err != nil { return nil, err } return output, nil
} // Close frees the handler resources
func (h *PforgeHandler) Close() { if h.handle != nil { C.pforge_handler_free(h.handle) h.handle = nil }
} // HandlerFunc is a function type for handlers
type HandlerFunc func(params map[string]interface{}) (map[string]interface{}, error) // Register creates a handler from a function
func Register(name string, fn HandlerFunc) Handler { return &funcHandler{fn: fn}
} type funcHandler struct { fn HandlerFunc
} func (h *funcHandler) Handle(params map[string]interface{}) (map[string]interface{}, error) { return h.fn(params)
}

