func (j *JSONProcessor) Handle(params map[string]interface{}) (map[string]interface{}, error) { data, ok := params["data"].(map[string]interface{}) if !ok { return nil, errors.New("invalid data parameter") } return j.processData(data, params)
} func (j *JSONProcessor) processData(data map[string]interface{}, params map[string]interface{}) (map[string]interface{}, error) { if schema, hasSchema := params["schema"].(map[string]interface{}); hasSchema { return j.validationResult(data, schema), nil } if operation, hasOp := params["operation"].(string); hasOp { return j.transformResult(data, operation), nil } if filter, hasFilter := params["filter"].(string); hasFilter { return j.filterResult(data, filter), nil } return nil, errors.New("must provide schema, operation, or filter")
} func (j *JSONProcessor) validationResult(data, schema map[string]interface{}) map[string]interface{} { errors := j.validate(data, schema) return map[string]interface{}{ "valid": len(errors) == 0, "errors": errors, }
} func (j *JSONProcessor) transformResult(data map[string]interface{}, operation string) map[string]interface{} { return map[string]interface{}{ "data": j.transform(data, operation), }
} func (j *JSONProcessor) filterResult(data map[string]interface{}, filter string) map[string]interface{} { return map[string]interface{}{ "data": j.filter(data, filter), }
