use tokio::process::Command; #[derive(Deserialize, JsonSchema)]
struct GrepInput { pattern: String, file: String, case_insensitive: bool, line_numbers: bool,
} #[derive(Serialize, JsonSchema)]
struct GrepOutput { stdout: String, stderr: String, exit_code: i32,
} pub struct GrepHandler; #[async_trait::async_trait]
impl Handler for GrepHandler { type Input = GrepInput; type Output = GrepOutput; type Error = Error; async fn handle(&self, input: Self::Input) -> Result<Self::Output> { let mut cmd = Command::new("grep"); if input.case_insensitive { cmd.arg("-i"); } if input.line_numbers { cmd.arg("-n"); } cmd.arg(&input.pattern); cmd.arg(&input.file); let output = cmd.output().await .map_err(|e| Error::Handler(format!("grep failed: {}", e)))?; Ok(GrepOutput { stdout: String::from_utf8_lossy(&output.stdout).to_string(), stderr: String::from_utf8_lossy(&output.stderr).to_string(), exit_code: output.status.code().unwrap_or(-1), }) }
