use std::sync::Arc;
use tokio::sync::RwLock;
use std::time::{SystemTime, UNIX_EPOCH}; struct TokenCache { access_token: String, expires_at: u64,
} pub struct OAuthHandler { client_id: String, client_secret: String, token_cache: Arc<RwLock<Option<TokenCache>>>, client: Client,
} impl OAuthHandler { async fn get_access_token(&self) -> Result<String> { let now = SystemTime::now() .duration_since(UNIX_EPOCH)? .as_secs(); // Check cache { let cache = self.token_cache.read().await; if let Some(token) = cache.as_ref() { if token.expires_at > now + 60 { // 1 minute buffer return Ok(token.access_token.clone()); } } } // Refresh token let response: TokenResponse = self.client .post("https://oauth.example.com/token") .form(&[ ("grant_type", "client_credentials"), ("client_id", &self.client_id), ("client_secret", &self.client_secret), ]) .send() .await? .json() .await?; let expires_at = now + response.expires_in; // Update cache { let mut cache = self.token_cache.write().await; *cache = Some(TokenCache { access_token: response.access_token.clone(), expires_at, }); } Ok(response.access_token) } async fn handle(&self, input: OAuthInput) -> Result<ApiResponse> { let access_token = self.get_access_token().await?; let response = self.client .get(&format!("https://api.example.com/{}", input.resource)) .bearer_auth(&access_token) .send() .await?; Ok(ApiResponse { status: response.status().as_u16(), body: response.json().await?, }) }
}

