use rand::Rng; async fn retry_with_jitter<F, Fut, T>( max_attempts: u32, base_delay_ms: u64, operation: F,
) -> Result<T>
where F: Fn() -> Fut, Fut: std::future::Future<Output = Result<T>>,
{ let mut attempt = 0; let mut rng = rand::thread_rng(); loop { match operation().await { Ok(result) => return Ok(result), Err(e) if attempt >= max_attempts - 1 => return Err(e), Err(_) => { let jitter = rng.gen_range(0..base_delay_ms / 2); let delay = (base_delay_ms * 2_u64.pow(attempt)) + jitter; tokio::time::sleep(Duration::from_millis(delay)).await; attempt += 1; } } }
}

