use std::sync::Arc;
use tokio::sync::RwLock;
use std::time::{Instant, Duration}; #[derive(Clone)]
enum CircuitState { Closed, Open { opened_at: Instant }, HalfOpen,
} struct CircuitBreaker { state: Arc<RwLock<CircuitState>>, failure_threshold: u32, timeout: Duration, failures: Arc<RwLock<u32>>,
} impl CircuitBreaker { async fn call<F, Fut, T>(&self, operation: F) -> Result<T> where F: FnOnce() -> Fut, Fut: std::future::Future<Output = Result<T>>, { // Check state let state = self.state.read().await.clone(); match state { CircuitState::Open { opened_at } => { if opened_at.elapsed() > self.timeout { // Transition to HalfOpen *self.state.write().await = CircuitState::HalfOpen; } else { return Err(Error::CircuitOpen); } } CircuitState::HalfOpen | CircuitState::Closed => {} } // Execute operation match operation().await { Ok(result) => { // Success - close circuit *self.state.write().await = CircuitState::Closed; *self.failures.write().await = 0; Ok(result) } Err(e) => { // Failure - increment counter let mut failures = self.failures.write().await; *failures += 1; if *failures >= self.failure_threshold { // Open circuit *self.state.write().await = CircuitState::Open { opened_at: Instant::now(), }; } Err(e) } } }
}

