use tokio::sync::Mutex; struct CachedHandler { client: Client, cache: Arc<Mutex<LruCache<String, serde_json::Value>>>,
} impl CachedHandler { async fn handle(&self, input: Input) -> Result<Output> { let cache_key = format!("{}-{}", input.resource, input.id); // Try API match self.client.get(&input.url).send().await { Ok(resp) if resp.status().is_success() => { let data: serde_json::Value = resp.json().await?; // Update cache self.cache.lock().await.put(cache_key.clone(), data.clone()); Ok(Output { data }) } _ => { // Fallback to cache if let Some(cached) = self.cache.lock().await.get(&cache_key) { tracing::warn!("Using cached response"); return Ok(Output { data: cached.clone() }); } Err(Error::Unavailable) } } }
