} impl TokenBucket { async fn acquire(&mut self) -> Result<()> { let now = Instant::now(); let elapsed = now.duration_since(self.last_refill).as_secs_f64(); // Refill tokens self.tokens = (self.tokens + elapsed * self.rate).min(self.capacity); self.last_refill = now; if self.tokens >= 1.0 { self.tokens -= 1.0; Ok(()) } else { let wait_time = ((1.0 - self.tokens) / self.rate) * 1000.0; tokio::time::sleep(Duration::from_millis(wait_time as u64)).await; self.tokens = 0.0; Ok(()) } }
