} impl AdaptiveTimeout { fn get_timeout(&self) -> Duration { if self.latencies.is_empty() { return Duration::from_secs(30); // Default } let avg: Duration = self.latencies.iter().sum::<Duration>() / self.latencies.len() as u32; avg * 3 // 3x average latency } fn record(&mut self, latency: Duration) { self.latencies.push_back(latency); if self.latencies.len() > self.window_size { self.latencies.pop_front(); } }
} async fn handle(&self, input: Input) -> Result<Output> { let timeout_duration = self.adaptive_timeout.lock().await.get_timeout(); let start = Instant::now(); let result = tokio::time::timeout( timeout_duration, self.client.get(&input.url).send() ).await??; self.adaptive_timeout.lock().await.record(start.elapsed()); Ok(result.json().await?)
}

