async fn execute(&self, input: Input) -> Result<Output> { let mut variables = input.variables; let mut results = Vec::new(); for step in &self.steps { match self.execute_step(step, &variables).await { Ok(output) => { if let Some(var) = &step.output_var { variables.insert(var.clone(), output.clone()); } results.push(StepResult { tool: step.tool.clone(), success: true, output: Some(output), error: None, }); } Err(e) if step.error_policy == ErrorPolicy::Continue => { results.push(StepResult { tool: step.tool.clone(), success: false, output: None, error: Some(e.to_string()), }); continue; } Err(e) => return Err(e), } } Ok(Output { results, variables })
