) -> bool { let parts: Vec<&str> = condition.split('.').collect(); if let Some(value) = variables.get(parts[0]) { // Navigate nested structure let mut current = value; for part in &parts[1..] { match current { Value::Object(map) => { if let Some(next) = map.get(*part) { current = next; } else { return false; } } _ => return false, } } // Check truthiness match current { Value::Bool(b) => *b, Value::Null => false, Value::Number(n) => n.as_f64().unwrap_or(0.0) != 0.0, Value::String(s) => !s.is_empty(), _ => true, } } else { false }
