Pattern 1: Drop Unused Variables fn cleanup_unused_variables( &mut self, current_step: usize,
) { let future_steps = &self.steps[current_step..]; self.variables.retain(|var_name, _| { // Keep if used in future steps future_steps.iter().any(|step| { step.uses_variable(var_name) }) });
} Pattern 2: Stream Large Data # BAD - store large data in variable
steps: - tool: fetch_large_file output_var: file_data # Could be MBs - tool: process input: { data: "{{file_data}}" } # GOOD - stream through tool
steps: - tool: fetch_and_process input: { url: "{{file_url}}" } # Tool streams data internally Pattern 3: Reference Counting (Future) use std::sync::Arc; struct PipelineState { variables: HashMap<String, Arc<Value>>,
} // Variables shared via Arc, clones are cheap
fn get_variable(&self, key: &str) -> Option<Arc<Value>> { self.variables.get(key).cloned()
}

