fn interpolate_variables( &self, template: &Value, variables: &HashMap<String, Value>,
) -> Value { match template { Value::String(s) => { let mut result = s.clone(); for (key, value) in variables { let pattern = format!("{{{{{}}}}}", key); if let Some(value_str) = value.as_str() { result = result.replace(&pattern, value_str); } } Value::String(result) } Value::Object(obj) => { let mut new_obj = serde_json::Map::new(); for (k, v) in obj { new_obj.insert(k.clone(), self.interpolate_variables(v, variables)); } Value::Object(new_obj) } Value::Array(arr) => { Value::Array( arr.iter() .map(|v| self.interpolate_variables(v, variables)) .collect() ) } other => other.clone(), }
}

