) -> Result<(Output, Checkpoint)> { let start_step = checkpoint.as_ref().map(|c| c.step_index).unwrap_or(0); let mut variables = checkpoint .map(|c| c.variables) .unwrap_or(input.variables); for (i, step) in self.steps.iter().enumerate().skip(start_step) { let result = self.execute_step(step, &variables).await?; if let Some(var) = &step.output_var { variables.insert(var.clone(), result); } // Save checkpoint after each step let checkpoint = Checkpoint { step_index: i + 1, variables: variables.clone(), }; save_checkpoint(&checkpoint)?; } Ok((Output { variables: variables.clone() }, Checkpoint { step_index: self.steps.len(), variables, }))
}

